Item.method_code:
const iomInv = aras.IomInnovator;
const { itemType } = options;
const item = window.getItem();
const managed_by_id = aras.getItemProperty(item, 'managed_by_id');
const currentUserId = aras.getUserID();
const resultOptions = { hidden:true, disabled: true };
var hiddenFlg = true;
var disabledFlg = false;
// ユーザからエイリアスアイデンティティを取得
var alias = iomInv.newItem("Alias", "get");
alias.setProperty("source_id", currentUserId);
alias.setAttribute('select', 'related_id');
alias = alias.apply();
var aliasId = alias.getProperty("related_id");

//managed_byのアイデンティティにユーザのエイリアスアイデンティティが含まれるかどうか判定
var identityList= aras.getIdentityList();
var isMember = false;

if(managed_by_id == null || managed_by_id == "")
{
    isMember = false;
}
else
{
   isMember = (identityList.indexOf(managed_by_id) >= 0); 
}

if(isMember)
{
    hiddenFlg = false;
}
else
{
    hiddenFlg = true;
}

if(!hiddenFlg)
{
    if(!disabledFlg)
    {
        Object.assign(resultOptions, { hidden:false, disabled: false });
    }
    else
    {
        Object.assign(resultOptions, { hidden:false, disabled: true });
    }
}
else
{
    Object.assign(resultOptions, { hidden:true, disabled: true });
}
return resultOptions;
